package com.aliothmoon.maafw.once;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.file.*;
import java.util.*;
public class RootUniqueRefinedScopeTest {
 @Test public void exactlySixPhaseClaimsAndNoOverrun(){assertTrue(RootUniqueRefinedScope.ACTIVE);assertEquals(3,RootUniqueRefinedScope.MAX_PER_PHASE);assertEquals(6,RootUniqueRefinedScope.MAX_FRAMES);Set<String> slots=new HashSet<>();for(var p:NativeRewardCardSession.Phase.values())for(int i=1;i<=3;i++)assertTrue(slots.add(RootUniqueRefinedScope.slot(p,i)));assertEquals(Set.of("BEFORE_1","BEFORE_2","BEFORE_3","AFTER_1","AFTER_2","AFTER_3"),slots);for(int i:new int[]{Integer.MIN_VALUE,-1,0,4,Integer.MAX_VALUE}){assertFalse(RootUniqueRefinedScope.validIndex(i));assertThrows(SecurityException.class,()->RootUniqueRefinedScope.slot(NativeRewardCardSession.Phase.BEFORE,i));}assertThrows(SecurityException.class,()->RootUniqueRefinedScope.slot(null,1));}
 @Test public void halfOpenAdmissionKeepsOriginal180s(){long s=RootUniqueRefinedScope.STARTS_UTC,e=RootUniqueRefinedScope.EXPIRES_UTC;assertFalse(RootUniqueRefinedScope.current(s-1));assertTrue(RootUniqueRefinedScope.current(s));assertTrue(RootUniqueRefinedScope.current(e-1));assertFalse(RootUniqueRefinedScope.current(e));assertTrue(RootUniqueRefinedScope.admissionCurrent(e-180001));assertFalse(RootUniqueRefinedScope.admissionCurrent(e-180000));assertEquals(181000,RootUniqueRefinedScope.sessionDeadline(1000,s));}
 @Test public void phaseDeadlineCannotExceedParentOrUtc(){long u=RootUniqueRefinedScope.STARTS_UTC;assertEquals(91000,RootUniqueRefinedScope.deadline(1000,u,181000));assertEquals(181000,RootUniqueRefinedScope.deadline(101000,u+100000,181000));assertEquals(1500,RootUniqueRefinedScope.deadline(1000,u,1500));assertEquals(1001,RootUniqueRefinedScope.deadline(1000,RootUniqueRefinedScope.EXPIRES_UTC-1,181000));}
 @Test public void invalidClocksFailClosed(){long u=RootUniqueRefinedScope.STARTS_UTC;assertThrows(SecurityException.class,()->RootUniqueRefinedScope.sessionDeadline(-1,u));assertThrows(SecurityException.class,()->RootUniqueRefinedScope.sessionDeadline(Long.MAX_VALUE,u));assertThrows(SecurityException.class,()->RootUniqueRefinedScope.sessionDeadline(1,RootUniqueRefinedScope.EXPIRES_UTC));assertThrows(SecurityException.class,()->RootUniqueRefinedScope.deadline(1,u,1));assertThrows(SecurityException.class,()->RootUniqueRefinedScope.deadline(-1,u,100));assertThrows(SecurityException.class,()->RootUniqueRefinedScope.deadline(Long.MAX_VALUE,u,Long.MAX_VALUE));}
 @Test public void onlyNewNamespaceAndFixedActionSlots()throws Exception{assertEquals(15,RootUniqueRefinedScope.SOURCE_TASK_ID);assertNotEquals(RootUniqueRefinedScope.DIRECTORY,RootUniquePendingScope.DIRECTORY);assertNotEquals(RootUniqueRefinedScope.DIRECTORY,RootSelectedPendingScope.DIRECTORY);assertNotEquals(RootUniqueRefinedScope.DIRECTORY,RootStatusRecoveryScope.DIRECTORY);assertNotEquals(RootUniqueRefinedScope.DIRECTORY,RootBoundedBusinessScope.DIRECTORY);assertNotEquals(RootUniqueRefinedScope.DIRECTORY,RootCurrentCardScope.DIRECTORY);assertNotEquals(RootUniqueRefinedScope.DIRECTORY,RootImageSeriesScope.DIRECTORY);assertNotEquals(RootUniqueRefinedScope.DIRECTORY,RootFamilyDiagnosticProfile.DIRECTORY);assertNotEquals(RootUniqueRefinedScope.DIRECTORY,AutonomousRewardCardScope.DIRECTORY);assertNotEquals(RootUniqueRefinedScope.DIRECTORY,RootCaptureScope.PREFLIGHT_DIRECTORY);assertThrows(SecurityException.class,()->RootUniqueRefinedScope.store(null,NativeRewardCardSession.Phase.BEFORE,1));assertThrows(SecurityException.class,()->RootUniqueRefinedScope.burnAction(Path.of("unused"),"BEFORE","safe"));assertThrows(SecurityException.class,()->RootUniqueRefinedScope.burnAction(Path.of("unused"),"../TAP","safe"));assertThrows(SecurityException.class,()->RootUniqueRefinedScope.burnAction(null,"TAP","safe"));}
 @Test public void badClaimsAndOversizedMetadataNeverWrite()throws Exception{var store=RootUniqueRefinedScope.store(Path.of("unused"),NativeRewardCardSession.Phase.BEFORE,1);assertThrows(SecurityException.class,()->store.burn("invalid","safe"));assertThrows(SecurityException.class,()->store.burn("11111111-1111-1111-1111-111111111111",null));assertThrows(SecurityException.class,()->store.burn("11111111-1111-1111-1111-111111111111","x".repeat(2049)));assertThrows(SecurityException.class,()->RootUniqueRefinedScope.burnAction(Path.of("unused"),"RETURN",null));}
 @Test public void durablePrimitiveHasNoRecoveryOrTruncate()throws Exception{Path p=Path.of("../app/src/main/java/com/aliothmoon/maafw/once/RootUniqueRefinedScope.java");if(!Files.exists(p))p=Path.of("app/src/main/java/com/aliothmoon/maafw/once/RootUniqueRefinedScope.java");String s=Files.readString(p);assertTrue(s.contains("StandardOpenOption.CREATE_NEW"));assertTrue(s.contains("c.force(true)"));assertFalse(s.contains("delete("));assertFalse(s.contains("TRUNCATE_EXISTING"));assertTrue(s.contains("maxFrames=6 maxPerPhase=3 maxTap=1 maxReturn=1"));}
}
